create extension if not exists pgcrypto;

create table if not exists public.store_settings (
  id text primary key default 'main' check (id = 'main'),
  data jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now()
);
create table if not exists public.categories (
  id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique,
  description text, emoji text not null default '🍇', sort_order integer not null default 0, active boolean not null default true,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.products (
  id uuid primary key default gen_random_uuid(), category_id uuid references public.categories(id) on delete set null,
  name text not null, description text, image_url text, price numeric(10,2) not null default 0 check (price >= 0),
  sizes jsonb not null default '[]'::jsonb, tags text[] not null default '{}', builder boolean not null default false, active boolean not null default true, featured boolean not null default false,
  sort_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.addons (
  id uuid primary key default gen_random_uuid(), name text not null, description text,
  price numeric(10,2) not null default 0 check (price >= 0), active boolean not null default true,
  sort_order integer not null default 0, created_at timestamptz not null default now()
);
create table if not exists public.product_addons (
  product_id uuid not null references public.products(id) on delete cascade,
  addon_id uuid not null references public.addons(id) on delete cascade, primary key (product_id, addon_id)
);
create table if not exists public.coupons (
  id uuid primary key default gen_random_uuid(), code text not null unique,
  discount_type text not null check (discount_type in ('percent','fixed')),
  discount_value numeric(10,2) not null check (discount_value > 0), min_order numeric(10,2) not null default 0 check (min_order >= 0),
  starts_at timestamptz, expires_at timestamptz, max_uses integer check (max_uses is null or max_uses > 0),
  uses_count integer not null default 0 check (uses_count >= 0), active boolean not null default true,
  created_at timestamptz not null default now()
);
create table if not exists public.orders (
  id uuid primary key default gen_random_uuid(), order_number bigint generated by default as identity unique,
  customer_name text not null, customer_phone text, fulfillment text not null default 'pickup' check (fulfillment in ('pickup','delivery')),
  delivery_address text, notes text, items jsonb not null default '[]'::jsonb,
  subtotal numeric(10,2) not null default 0 check (subtotal >= 0), discount numeric(10,2) not null default 0 check (discount >= 0),
  delivery_fee numeric(10,2) not null default 0 check (delivery_fee >= 0), total numeric(10,2) not null default 0 check (total >= 0),
  coupon_code text, customer_details jsonb not null default '{}'::jsonb, status text not null default 'received' check (status in ('received','confirmed','preparing','ready','out_for_delivery','completed','cancelled')),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index if not exists products_category_active_sort_idx on public.products(category_id, active, sort_order);
create index if not exists categories_active_sort_idx on public.categories(active, sort_order);
create index if not exists addons_active_sort_idx on public.addons(active, sort_order);
create index if not exists coupons_active_code_idx on public.coupons(active, code);
create index if not exists orders_created_at_idx on public.orders(created_at desc);
create index if not exists orders_status_created_at_idx on public.orders(status, created_at desc);

alter table public.store_settings enable row level security;
alter table public.categories enable row level security;
alter table public.products enable row level security;
alter table public.addons enable row level security;
alter table public.product_addons enable row level security;
alter table public.coupons enable row level security;
alter table public.orders enable row level security;

grant select on public.store_settings, public.categories, public.products, public.addons, public.product_addons, public.coupons to anon, authenticated;
grant insert on public.orders to anon, authenticated;
grant select, insert, update, delete on public.store_settings, public.categories, public.products, public.addons, public.product_addons, public.coupons, public.orders to authenticated;
grant usage, select on all sequences in schema public to anon, authenticated;

create policy "public can read store settings" on public.store_settings for select to anon, authenticated using (true);
create policy "admins manage store settings" on public.store_settings for all to authenticated using ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin') with check ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');
create policy "public can read active categories" on public.categories for select to anon, authenticated using (active = true or (select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');
create policy "admins manage categories" on public.categories for all to authenticated using ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin') with check ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');
create policy "public can read active products" on public.products for select to anon, authenticated using (active = true or (select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');
create policy "admins manage products" on public.products for all to authenticated using ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin') with check ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');
create policy "public can read active addons" on public.addons for select to anon, authenticated using (active = true or (select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');
create policy "admins manage addons" on public.addons for all to authenticated using ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin') with check ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');
create policy "public can read product addons" on public.product_addons for select to anon, authenticated using (true);
create policy "admins manage product addons" on public.product_addons for all to authenticated using ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin') with check ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');
create policy "public can read active coupons" on public.coupons for select to anon, authenticated using (active = true or (select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');
create policy "admins manage coupons" on public.coupons for all to authenticated using ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin') with check ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');
create policy "customers can create orders" on public.orders for insert to anon, authenticated with check (status = 'received');
create policy "admins can view orders" on public.orders for select to authenticated using ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');
create policy "admins can update orders" on public.orders for update to authenticated using ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin') with check ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');
create policy "admins can delete orders" on public.orders for delete to authenticated using ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('product-images', 'product-images', true, 5242880, array['image/jpeg','image/png','image/webp']) on conflict (id) do nothing;
create policy "public can view product images" on storage.objects for select to anon, authenticated using (bucket_id = 'product-images');
create policy "admins upload product images" on storage.objects for insert to authenticated with check (bucket_id = 'product-images' and (select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');
create policy "admins update product images" on storage.objects for update to authenticated using (bucket_id = 'product-images' and (select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin') with check (bucket_id = 'product-images' and (select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');
create policy "admins delete product images" on storage.objects for delete to authenticated using (bucket_id = 'product-images' and (select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');
